import { Flow, wfa } from '@servicenow/sdk/automation'
import { trigger } from '@servicenow/sdk/automation'

// Flow that defines an incident record trigger with conditions and non-default runtime options.

Flow(
    {
        $id: Now.ID['flow_trigger_incident_with_conditions'],
        name: 'Flow - Trigger Incident With Conditions',
        description: 'Flow used by tests to validate incident record trigger configuration with conditions.',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'MEDIUM',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['trigger_incident_with_conditions'], annotation: 'Trigger incident with conditions' },
        {
            table: 'incident',
            condition: 'active=true^priority=1',
            run_on_extended: 'true',
            run_flow_in: 'foreground',
            run_when_user_list: [],
            run_when_setting: 'interactive',
            run_when_user_setting: 'one_of',
        }
    ),
    (_trigger) => {
        // no-op body; this test focuses on trigger configuration only
    }
)
